const spin = stylex.keyframes({
  to: { transform: "rotate(360deg)" },
});

const styles = stylex.create({
  spinner: {
    display: "inline-flex",
    width: 16,
    height: 16,
    color: raster.ink,
    verticalAlign: "middle",
  },
  ring: {
    display: "block",
    width: 16,
    height: 16,
    animationName: {
      default: spin,
