      default: raster.radius,
      [phone]: 0,
    },
    backgroundColor: raster.paper,
    color: raster.ink,
    boxShadow: {
      default: "0 8px 24px rgba(0,0,0,0.06)",
      [phone]: "none",
    },
    padding: {
      default: 14,
      [phone]: 16,
    },
    width: {
      default: 240,
      [phone]: "min(320px, calc(100vw - 32px))",
    },
    fontSize: {
      default: 13,
      [phone]: 16,
    },
    lineHeight: 1.55,
    letterSpacing: "-0.01em",
  },
