const styles = stylex.create({
  multi: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(184px, 1fr))",
    gap: 20,
  },
  cap: {
    marginTop: 0,
    marginRight: 0,
    marginBottom: 8,
    marginLeft: 0,
    fontSize: 12,
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: raster.ink,
  },
