import * as React from "react";
import {
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  PLOT,
  SrTable,
  barMark,
  chartStyles,
  defaultFormat,
  niceMax,
  stackedRows,
  ticksFor,
  type ChartSeries,
} from "./frame";
import { rs } from "../rs";

export type BarOrientation = "vertical" | "horizontal";

export interface BarChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data?: Array<{ label: string; value: number }>;
  series?: ChartSeries[];
  labels?: string[];
  height?: number;
  orientation?: BarOrientation;
  stacked?: boolean;
  inverted?: boolean;
  grid?: boolean;
  ticks?: number;
  unit?: string;
  yLabel?: string;
  spot?: boolean | string;
  valueFormat?: (value: number) => string;
}

export function BarChart({
  data,
  series,
  labels,
  height = 204,
  orientation = "vertical",
  stacked,
  inverted,
  grid = true,
  ticks = 4,
  unit,
  yLabel,
  spot,
  valueFormat,
  className,
  ...props
}: BarChartProps) {
  const fromData: ChartSeries[] = data ? [{ name: "Value", values: data.map((d) => d.value) }] : [];
  const shown = (series ?? fromData).slice(0, 4);
  const tickLabels = labels ?? data?.map((d) => d.label) ?? shown[0]?.values.map((_, i) => `${i + 1}`) ?? [];
  const n = tickLabels.length;
  const stacks = stacked && shown.length > 1 ? stackedRows(shown) : null;
  const rawMax = stacks
    ? Math.max(...stacks.map((row) => row[row.length - 1] ?? 0))
    : Math.max(0, ...shown.flatMap((s) => s.values));
  const max = niceMax(rawMax);
  const format = valueFormat ?? ((v: number) => defaultFormat(v));
  const tip = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const [hover, setHover] = React.useState<number | null>(null);

  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const horizontal = orientation === "horizontal";
  const band = (horizontal ? plotH : plotW) / Math.max(1, n);
  const barThick = Math.min(8, Math.max(2, band - 1));
  const inset = (band - barThick) / 2;
  const yV = (v: number) => {
    const t = v / max;
    return inverted ? MT + t * plotH : MT + plotH - t * plotH;
  };
  const xV = (v: number) => ML + (v / max) * plotW;
  const tickVals = ticksFor(max, ticks);
  const labelEvery = Math.ceil(n / 8);

  const svg = rs([], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);

  return (
    <ChartField spot={spot} className={className} {...props}>
      {yLabel && (
        <ChartHead>
          <ChartTitle>{yLabel}</ChartTitle>
        </ChartHead>
      )}
      <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} role="img" aria-label="Bar chart">
        <g className={plot.className} style={plot.style}>
          {grid &&
            tickVals.map((t) =>
              horizontal ? (
                <g key={t}>
                  <line className={gridSx.className} style={gridSx.style} x1={xV(t)} x2={xV(t)} y1={MT} y2={height - MB} />
                  <text className={axis.className} style={axis.style} x={xV(t)} y={height - 4} textAnchor="middle">
                    {format(t)}
                  </text>
                </g>
              ) : (
                <g key={t}>
                  <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={yV(t)} y2={yV(t)} />
                  <text className={axis.className} style={axis.style} x={ML - 6} y={yV(t) + 3.5} textAnchor="end">
                    {format(t)}
                  </text>
                </g>
              ),
            )}
          {tickLabels.map((label, i) => {
            const values = shown.map((s) => s.values[i] ?? 0);
            const mark = (si: number) =>
              barMark({
                spot: Boolean(spot) && (stacks ? si === 0 : true),
                muted: hover != null && hover !== i,
              });
            if (horizontal) {
              const y0 = MT + i * band + inset;
              if (stacks) {
                let prev = 0;
                return shown.map((s, si) => {
                  const v = s.values[i] ?? 0;
                  const x1 = xV(prev);
                  const x2 = xV(prev + v);
                  prev += v;
                  return (
                    <rect
                      key={`${label}-${s.name}`}
                      {...mark(si)}
                      x={x1}
                      y={y0}
                      width={Math.max(0, x2 - x1)}
                      height={barThick}
                      onMouseEnter={() => setHover(i)}
                      onMouseLeave={() => setHover(null)}
                    />
                  );
                });
              }
              const v = values[0] ?? 0;
              return (
                <rect
                  key={label}
                  {...mark(0)}
                  x={ML}
                  y={y0}
                  width={Math.max(0, xV(v) - ML)}
                  height={barThick}
                  onMouseEnter={() => setHover(i)}
                  onMouseLeave={() => setHover(null)}
                />
              );
            }
            const x0 = ML + i * band + inset;
            if (stacks) {
              let prev = 0;
              return shown.map((s, si) => {
                const v = s.values[i] ?? 0;
                const y1 = yV(prev + v);
                const y2 = yV(prev);
                prev += v;
                return (
                  <rect
                    key={`${label}-${s.name}`}
                    {...mark(si)}
                    x={x0}
                    y={y1}
                    width={barThick}
                    height={Math.max(0, y2 - y1)}
                    onMouseEnter={() => setHover(i)}
                    onMouseLeave={() => setHover(null)}
                  />
                );
              });
            }
            const v = values[0] ?? 0;
            return (
              <rect
                key={label}
                {...mark(0)}
                x={x0}
                y={yV(v)}
                width={barThick}
                height={Math.max(0, yV(0) - yV(v))}
                onMouseEnter={() => setHover(i)}
                onMouseLeave={() => setHover(null)}
              />
            );
          })}
          <line
            className={baseline.className}
            style={baseline.style}
            x1={ML}
            x2={horizontal ? ML : W - MR}
            y1={horizontal ? MT : yV(0)}
            y2={horizontal ? height - MB : yV(0)}
          />
          {tickLabels.map(
            (label, i) =>
              i % labelEvery === 0 && (
                <text
                  key={label}
                  className={axis.className}
                  style={axis.style}
                  x={horizontal ? ML - 6 : ML + i * band + band / 2}
                  y={horizontal ? MT + i * band + band / 2 + 3 : height - 4}
                  textAnchor={horizontal ? "end" : "middle"}
                >
                  {label}
                </text>
              ),
          )}
        </g>
      </svg>
      {unit && (
        <ChartLegend aria-hidden="true">
          <ChartLegendItem>{unit}</ChartLegendItem>
        </ChartLegend>
      )}
      {hover != null && tickLabels[hover] && (
        <ChartTip
          left={horizontal ? "50%" : `${((ML + hover * band + band / 2) / W) * 100}%`}
          top={horizontal ? `${((MT + hover * band) / height) * 100}%` : `${(yV(shown[0]?.values[hover] ?? 0) / height) * 100}%`}
          label={tickLabels[hover]}
          rows={shown.map((s) => ({ name: shown.length > 1 ? s.name : undefined, value: tip(s.values[hover] ?? 0) }))}
        />
      )}
      <SrTable caption="Chart data" labels={tickLabels} series={shown} />
    </ChartField>
  );
}

import * as React from "react";
import {
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  LegendSwatch,
  PLOT,
  SrTable,
  chartStyles,
  defaultFormat,
  scatterMark,
  ticksBetween,
  type ChartAnnotation,
  type ChartPoint,
} from "./frame";
import { rs } from "../rs";

export type ScatterChartProps = React.HTMLAttributes<HTMLDivElement> & {
  points: ChartPoint[];
  height?: number;
  unit?: string;
  xLabel?: string;
  yLabel?: string;
  xDomain?: [number, number];
  yDomain?: [number, number];
  grid?: boolean;
  ticks?: number;
  annotations?: ChartAnnotation[];
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
};

function extent(values: number[], pad = 0.08): [number, number] {
  const lo = Math.min(...values);
  const hi = Math.max(...values);
  const span = hi - lo || 1;
  return [lo - span * pad, hi + span * pad];
}

export function ScatterChart({
  points,
  height = 204,
  unit,
  xLabel,
  yLabel,
  xDomain,
  yDomain,
  grid = true,
  ticks = 4,
  annotations = [],
  valueFormat,
  className,
  spot,
  ...props
}: ScatterChartProps) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v));
  const [hover, setHover] = React.useState<number | null>(null);
  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const [xMin, xMax] = xDomain ?? extent(xs);
  const [yMin, yMax] = yDomain ?? extent(ys);
  const yTicks = ticksBetween(yMin, yMax, ticks);
  const xTicks = ticksBetween(xMin, xMax, ticks);
  const toX = (x: number) => ML + ((x - xMin) / (xMax - xMin || 1)) * plotW;
  const toY = (y: number) => MT + plotH - ((y - yMin) / (yMax - yMin || 1)) * plotH;
  const groups = [...new Set(points.map((p) => p.group).filter(Boolean))] as string[];
  const active = hover != null ? points[hover] : null;

  const svg = rs([], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);
  const cursor = rs(["rs-chart-cursor"], chartStyles.cursor);
  const ann = rs(["rs-chart-ann"], chartStyles.ann);
  const mark = scatterMark(Boolean(spot));

  return (
    <ChartField spot={spot} className={className} {...props}>
      {(yLabel || xLabel) && (
        <ChartHead>
          {yLabel ? <ChartTitle>{yLabel}</ChartTitle> : <span />}
          {xLabel ? <ChartTitle>{xLabel}</ChartTitle> : null}
        </ChartHead>
      )}
      <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} role="img" aria-label="Scatter">
        <g className={plot.className} style={plot.style}>
          {grid &&
            yTicks.map((t) => (
              <g key={`yg-${t}`}>
                <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={toY(t)} y2={toY(t)} />
                <text className={axis.className} style={axis.style} x={ML - 6} y={toY(t) + 3.5} textAnchor="end">
                  {format(t)}
                </text>
              </g>
            ))}
          {grid &&
            xTicks.map((t) => (
              <line key={`xg-${t}`} className={gridSx.className} style={gridSx.style} x1={toX(t)} x2={toX(t)} y1={MT} y2={MT + plotH} />
            ))}
          <line className={baseline.className} style={baseline.style} x1={ML} x2={ML} y1={MT} y2={MT + plotH} />
          <line className={baseline.className} style={baseline.style} x1={ML} x2={W - MR} y1={MT + plotH} y2={MT + plotH} />
          {xTicks.map((t) => (
            <text key={`xl-${t}`} className={axis.className} style={axis.style} x={toX(t)} y={height - 4} textAnchor="middle">
              {format(t)}
            </text>
          ))}
          {annotations.map((a) => (
            <g key={`${a.at}-${a.label}`}>
              <line className={cursor.className} style={cursor.style} x1={toX(a.at)} x2={toX(a.at)} y1={MT} y2={MT + plotH} />
              <text className={ann.className} style={ann.style} x={toX(a.at) + 4} y={MT + 10}>
                {a.label}
              </text>
            </g>
          ))}
          {points.map((p, i) => (
            <circle
              key={i}
              className={mark.className}
              style={mark.style}
              cx={toX(p.x)}
              cy={toY(p.y)}
              r={hover === i ? 3.5 : 2.25}
              onMouseEnter={() => setHover(i)}
              onMouseLeave={() => setHover(null)}
            />
          ))}
        </g>
      </svg>
      {active && (
        <ChartTip
          left={`${(toX(active.x) / W) * 100}%`}
          top={`${(toY(active.y) / height) * 100}%`}
          label={active.label ?? `${format(active.x)} · ${format(active.y)}`}
          rows={[{ name: active.group, value: format(active.y) }]}
        />
      )}
      {(groups.length > 0 || unit) && (
        <ChartLegend aria-hidden="true">
          {groups.map((g) => (
            <ChartLegendItem key={g}>
              <LegendSwatch seriesIndex={0} spot={Boolean(spot)} />
              {g}
            </ChartLegendItem>
          ))}
          {unit ? <ChartLegendItem>{unit}</ChartLegendItem> : null}
        </ChartLegend>
      )}
      <SrTable
        caption="Scatter data"
        labels={points.map((p) => p.label ?? `${p.x}`)}
        series={[{ name: "y", values: points.map((p) => p.y) }]}
      />
    </ChartField>
  );
}

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "../tokens.stylex";
import { rs } from "../rs";
import { ChartField, ChartLegend, ChartLegendItem, ChartTitle, chartStyles, defaultFormat } from "./frame";

const styles = stylex.create({
  donut: {
    display: "block",
  },
  track: {
    fill: "none",
    stroke: raster.divider,
    strokeWidth: 1,
  },
  value: {
    fill: "none",
    stroke: "var(--rs-chart-spot)",
    strokeWidth: 1,
    strokeLinecap: "butt",
  },
  label: {
    fill: raster.ink,
    fontSize: 12,
    fontWeight: 500,
    letterSpacing: "-0.03em",
    fontVariantNumeric: "tabular-nums",
  },
  caption: {
    fill: raster.gray,
    fontSize: 8,
    fontWeight: 500,
    letterSpacing: "0.06em",
  },
  share: {
    display: "flex",
    height: 8,
    width: "100%",
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: 0,
    boxShadow: "none",
  },
  seg: {
    height: "100%",
    borderRadius: 0,
    backgroundColor: {
      default: raster.ink,
      ":nth-child(2)": raster.gray,
      ":nth-child(3)": raster.divider,
    },
    transition: "fill var(--duration-snap) var(--ease), opacity var(--duration-snap) var(--ease)",
  },
  segSpot: {
    backgroundColor: "var(--rs-chart-spot)",
  },
});

export interface DonutProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  max?: number;
  size?: number;
  label?: React.ReactNode;
  unit?: string;
  valueFormat?: (value: number) => string;
  spot?: boolean | string;
}

const R = 36;
const C = 2 * Math.PI * R;

export function Donut({
  value,
  max = 100,
  size = 184,
  label,
  unit,
  valueFormat,
  className,
  spot,
  ...props
}: DonutProps) {
  const format = valueFormat ?? ((v: number) => `${Math.round((v / max) * 100)}%`);
  const pct = Math.max(0, Math.min(1, max === 0 ? 0 : value / max));
  const caption = typeof label === "string" ? label : undefined;
  const svg = rs(["rs-chart-plot", "rs-chart-donut"], chartStyles.svg, chartStyles.plot, styles.donut);
  const track = rs(["rs-chart-donut-track"], styles.track);
  const valueSx = rs(["rs-chart-donut-value"], styles.value);
  const labelSx = rs(["rs-chart-donut-label"], styles.label);
  const captionSx = rs(["rs-chart-donut-caption"], styles.caption);
  return (
    <ChartField spot={spot} className={className ? `rs-chart-donut-wrap ${className}` : "rs-chart-donut-wrap"} {...props}>
      <svg
        className={svg.className}
        style={svg.style}
        width={size}
        height={size}
        viewBox="0 0 96 96"
        role="img"
        aria-label={`${format(value)}${caption ? ` ${caption}` : ""}`}
      >
        <circle className={track.className} style={track.style} cx="48" cy="48" r={R} />
        <circle
          className={valueSx.className}
          style={valueSx.style}
          cx="48"
          cy="48"
          r={R}
          strokeDasharray={`${pct * C} ${C}`}
          transform="rotate(-90 48 48)"
        />
        <text className={labelSx.className} style={labelSx.style} x="48" y={caption ? 46 : 49} textAnchor="middle">
          {format(value)}
          {unit ? ` ${unit}` : ""}
        </text>
        {caption && (
          <text className={captionSx.className} style={captionSx.style} x="48" y="57" textAnchor="middle">
            {caption}
          </text>
        )}
      </svg>
      {label && !caption ? <ChartTitle>{label}</ChartTitle> : null}
    </ChartField>
  );
}

export type ShareSlice = { label: string; value: number };

export interface ShareProps extends React.HTMLAttributes<HTMLDivElement> {
  slices: ShareSlice[];
  unit?: string;
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
}

export function Share({
  slices,
  unit,
  valueFormat,
  className,
  spot,
  ...props
}: ShareProps) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const total = slices.reduce((s, x) => s + x.value, 0) || 1;
  const share = rs(["rs-chart-share"], styles.share);
  return (
    <ChartField spot={spot} className={className} {...props}>
      <div className={share.className} style={share.style} role="img" aria-label="Share">
        {slices.map((s, i) => {
          const seg = rs(
            ["rs-chart-share-seg", i === 0 && "rs-chart-share-seg-spot"],
            styles.seg,
            i === 0 && styles.segSpot,
          );
          return (
            <div
              key={s.label}
              className={seg.className}
              style={{ ...seg.style, flex: `${s.value} 1 0` }}
              title={`${s.label} ${format(s.value)}`}
            />
          );
        })}
      </div>
      <ChartLegend aria-hidden="true">
        {slices.map((s) => (
          <ChartLegendItem key={s.label}>
            {s.label} {defaultFormat((s.value / total) * 100)}%
          </ChartLegendItem>
        ))}
      </ChartLegend>
    </ChartField>
  );
}

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "../tokens.stylex";
import { rs } from "../rs";
import {
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  PLOT,
  SrTable,
  chartStyles,
  defaultFormat,
  niceMax,
  ticksFor,
} from "./frame";

const styles = stylex.create({
  hist: {
    fill: raster.divider,
    stroke: "none",
    borderRadius: 0,
  },
});

export type HistogramBin = { label: string; count: number };

export interface HistogramProps extends React.HTMLAttributes<HTMLDivElement> {
  bins: HistogramBin[];
  height?: number;
  unit?: string;
  yLabel?: string;
  grid?: boolean;
  ticks?: number;
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
}

export function Histogram({
  bins,
  height = 204,
  unit,
  yLabel,
  grid = true,
  ticks = 4,
  valueFormat,
  className,
  spot,
  ...props
}: HistogramProps) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v));
  const tip = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const [hover, setHover] = React.useState<number | null>(null);
  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const max = niceMax(Math.max(...bins.map((b) => b.count), 1));
  const yTicks = ticksFor(max, ticks);
  const gap = 1;
  const bw = (plotW - gap * Math.max(0, bins.length - 1)) / bins.length;
  const active = hover != null ? bins[hover] : null;

  const svg = rs([], chartStyles.svg);
  const plot = rs(["rs-chart-plot"], chartStyles.plot);
  const gridSx = rs(["rs-chart-grid"], chartStyles.grid);
  const axis = rs(["rs-chart-axis"], chartStyles.axis);
  const baseline = rs(["rs-chart-baseline"], chartStyles.baseline);
  const hist = rs(["rs-chart-hist", spot && "rs-chart-bar-spot"], styles.hist, spot && chartStyles.barSpot);

  return (
    <ChartField spot={spot} className={className} {...props}>
      {yLabel && (
        <ChartHead>
          <ChartTitle>{yLabel}</ChartTitle>
        </ChartHead>
      )}
      <svg className={svg.className} style={svg.style} viewBox={`0 0 ${W} ${height}`} role="img" aria-label="Histogram">
        <g className={plot.className} style={plot.style}>
          {grid &&
            yTicks.map((t) => {
              const y = MT + plotH - (t / max) * plotH;
              return (
                <g key={t}>
                  <line className={gridSx.className} style={gridSx.style} x1={ML} x2={W - MR} y1={y} y2={y} />
                  <text className={axis.className} style={axis.style} x={ML - 6} y={y + 3.5} textAnchor="end">
                    {format(t)}
                  </text>
                </g>
              );
            })}
          <line className={baseline.className} style={baseline.style} x1={ML} x2={W - MR} y1={MT + plotH} y2={MT + plotH} />
          {bins.map((b, i) => {
            const h = (b.count / max) * plotH;
            const x = ML + i * (bw + gap);
            const y = MT + plotH - h;
            return (
              <g key={b.label} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}>
                <rect className={hist.className} style={hist.style} x={x} y={y} width={bw} height={h} />
                <text className={axis.className} style={axis.style} x={x + bw / 2} y={height - 4} textAnchor="middle">
                  {b.label}
                </text>
              </g>
            );
          })}
        </g>
      </svg>
      {active && (
        <ChartTip
          left={`${((ML + (hover ?? 0) * (bw + gap) + bw / 2) / W) * 100}%`}
          top={`${((MT + plotH - (active.count / max) * plotH) / height) * 100}%`}
          label={active.label}
          rows={[{ value: tip(active.count) }]}
        />
      )}
      {unit && (
        <ChartLegend aria-hidden="true">
          <ChartLegendItem>{unit}</ChartLegendItem>
        </ChartLegend>
      )}
      <SrTable
        caption="Histogram"
        labels={bins.map((b) => b.label)}
        series={[{ name: "count", values: bins.map((b) => b.count) }]}
      />
    </ChartField>
  );
}

