    strokeWidth: 1,
    strokeLinecap: "butt",
  },
  label: {
    fill: raster.ink,
    fontSize: 12,
    fontWeight: 500,
    letterSpacing: "-0.03em",
    fontVariantNumeric: "tabular-nums",
  },
  caption: {
    fill: raster.gray,
    fontSize: 8,
    fontWeight: 500,
    letterSpacing: "0.06em",
  },
  share: {
    display: "flex",
    height: 8,
    width: "100%",
    borderWidth: raster.hairline,
    borderStyle: "solid",
