import * as React from "react";
import {
  ChartField,
  ChartHead,
  ChartLegend,
  ChartLegendItem,
  ChartTip,
  ChartTitle,
  LegendSwatch,
  MAX_SERIES,
  PLOT,
  SrTable,
  areaMark,
